class Solution {
  public int largestPalindrome(int n) {
    if (n == 1) return 9;
    long upper = (long) Math.pow(10, n) - 1;
    long lower = (long) Math.pow(10, n - 1);
    for (long left = upper; left >= lower; left--) {
      String s = Long.toString(left);
      long palindrome = Long.parseLong(s + new StringBuilder(s).reverse());
      for (long factor = upper; factor * factor >= palindrome; factor--) {
        if (palindrome % factor == 0) return (int) (palindrome % 1337);
      }
    }
    return 0;
  }
}
